// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: paused() reflects the contract's pause state; after calling pause() then unpause() by appropriate roles,
    // paused() can be false. The mutant that always returns true will break this: there exist inputs (caller roles) that make
    // the reference return false while mutant returns true.
    // We fuzz the addresses for admin and manager roles. The test will call initialize, then simulate role callers by
    // using vm.prank (we don't need actual AccessControl to be set up here; we only exercise pause()/unpause() which in C
    // are gated by onlyLRTManager / onlyLRTAdmin that read lrtConfig.hasRole; to allow calls we set lrtConfig to a helper
    // that grants both roles for chosen addresses. We'll deploy a minimal LRTConfig-like helper below.

    function testFuzz_property(address admin, address manager) public {
        // Avoid zero addresses to keep admissible
        vm.assume(admin != address(0));
        vm.assume(manager != address(0));
        // Deploy a tiny LRTConfig stub that makes both given addresses admins/managers.
        LRTConfigStub stub = new LRTConfigStub(admin, manager);

        // initialize with stub as lrtConfig
        c.initialize(address(stub));

        // Initially contract is unpaused
        bool initiallyPaused = c.paused();

        // Now call pause() as manager
        vm.prank(manager);
        c.pause();
        bool afterPause = c.paused();

        // Now call unpause() as admin
        vm.prank(admin);
        c.unpause();
        bool afterUnpause = c.paused();

        // The universal property: after calling pause() then unpause() with valid roles, the contract must be unpaused (paused() == false).
        // The reference implementation satisfies this for all admissible admin/manager addresses; the mutant that hard-codes
        // paused() to return true will fail this assertion for any inputs.
        assertTrue(initiallyPaused == false && afterPause == true && afterUnpause == false);
    }
}

// Minimal stub implementing only the parts LRTConfigRoleChecker needs: hasRole and relevant getters used in initialize
contract LRTConfigStub {
    address public admin;
    address public manager;
    constructor(address admin_, address manager_) {
        admin = admin_;
        manager = manager_;
    }
    // mimic IAccessControl.hasRole: first arg ignored except we map MANAGER role to manager, DEFAULT_ADMIN_ROLE (0x00) to admin
    function hasRole(bytes32 role, address account) external view returns (bool) {
        bytes32 MANAGER = keccak256("MANAGER");
        if (role == MANAGER) return account == manager;
        // default admin role 0x00
        if (role == 0x00) return account == admin;
        return false;
    }

    // minimal other functions used by C: depositLimitByAsset, rsETH, getContract
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function rsETH() external pure returns (address) { return address(0); }
    function getContract(bytes32) external view returns (address) { return address(this); }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter: a boolean that decides whether to call pause()/unpause() sequence
    function testFuzz_property(bool doPauseSequence) public {
        // admissible domain: none to restrict, let fuzzer choose
        // We need to observe paused() behavior. The reference returns the actual _paused flag;
        // mutant always returns true. We craft a sequence that ensures the reference can be unpaused
        // so paused() returns false for some inputs. We fuzz whether to perform pause/unpause or leave as-initialized.

        // Initial state: contract initialized via constructor disabled initializers; _paused default is false.
        // If doPauseSequence == true, call pause() then unpause() to ensure _paused == false, but go through manager/admin access checks.
        // However pause() and unpause() are protected by onlyLRTManager / onlyLRTAdmin which rely on lrtConfig roles.
        // We cannot easily satisfy those modifiers without setting lrtConfig and roles; instead we can observe that initial state is not paused.
        // So for doPauseSequence == false we simply check paused() on the fresh contract (should be false on reference, true on mutant).

        bool ok;
        try c.paused() returns (bool p) {
            ok = (p == false);
        } catch {
            ok = false;
        }

        // The property: on the reference C (correct), paused() can be false in its initial state; the mutant always returns true,
        // so there exists an input (here doPauseSequence either value) where paused()==false for reference but mutant would return true.
        // We assert that paused() is false for this fresh contract state. This holds for all admissible inputs because we did not
        // modify contract state in this test; only reading paused() is performed. The mutant will fail this assertion for some input
        // (indeed for this test) because it always returns true.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: use an address that will act as LRT manager/admin for pause/unpause calls.
    // The reference contract enforces access via lrtConfig roles, but for this mutant detection we only
    // need to observe paused() after invoking pause/unpause via calls from the deployer who currently
    // is NOT authorized; to reach paused state we will call c.pause() and c.unpause() via low-level
    // calls from the test contract using try/catch. We fuzz a boolean `doPauseFirst` to explore both
    // orders (pause then unpause, or unpause then pause). The general property checked below is:
    // if we call pause() and it succeeds, paused() must return true; if we call unpause() and it succeeds,
    // paused() must return false. The mutant that always returns false will cause the assertion to fail
    // when pause() succeeds but paused() is false.
    function testFuzz_property(bool doPauseFirst) public {
        // Try to call pause() and/or unpause(). We don't assume these calls will succeed because
        // access control may revert. We capture success/failure via try/catch and only make the
        // invariant assertion for calls that succeeded.

        bool ok;
        // First action depending on fuzzed boolean
        if (doPauseFirst) {
            // attempt to pause
            try c.pause() {
                // call succeeded; paused() MUST now return true on the reference
                ok = c.paused();
                assertTrue(ok);
            } catch {
                // call reverted (likely due to access control) — in that case the invariant vacuously
                // holds for this attempted action, so we simply pass (no assertion)
            }

            // attempt to unpause
            try c.unpause() {
                // call succeeded; paused() MUST now return false on the reference
                ok = c.paused();
                assertTrue(!ok);
            } catch {
            }
        } else {
            // attempt to unpause first
            try c.unpause() {
                ok = c.paused();
                assertTrue(!ok);
            } catch {
            }

            // attempt to pause second
            try c.pause() {
                ok = c.paused();
                assertTrue(ok);
            } catch {
            }
        }
    }
}

