pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal stub of IAccessControl to set roles for testing via a fake lrtConfig we can control.
interface IAccessControlStub {
    function hasRole(bytes32 role, address account) external view returns (bool);
}

// Minimal LRTConfig stub implementing needed functions for C initialization and role checks
contract LRTConfigStub {
    address public lrtOracle;
    address public rseth;
    mapping(address => bool) public supported;
    mapping(bytes32 => address) public contracts;
    mapping(bytes32 => address) public tokens;
    mapping(bytes32 => mapping(address => bool)) public roles;
    mapping(address => uint256) public depositLimit;

    function setRole(bytes32 role, address account, bool v) external {
        roles[role][account] = v;
    }
    function isSupportedAsset(address asset) external view returns (bool) {
        return supported[asset];
    }
    function setSupported(address asset, bool v) external { supported[asset] = v; }
    function getContract(bytes32 k) external view returns (address) { return contracts[k]; }
    function setContract(bytes32 k, address addr) external { contracts[k] = addr; }
    function rsETH() external view returns (address) { return rseth; }
    function setRsETH(address a) external { rseth = a; }
    function depositLimitByAsset(address asset) external view returns (uint256) { return depositLimit[asset]; }
    function setDepositLimit(address asset, uint256 v) external { depositLimit[asset] = v; }
}

contract InvMutTest is Test {
    C c;
    LRTConfigStub cfg;

    function setUp() public {
        // deploy config stub and contract
        cfg = new LRTConfigStub();
        c = new C();
        // initialize with cfg address
        c.initialize(address(cfg));
    }

    // General rule: for any address that has the MANAGER role (fuzzed), calling pause() will make paused() return true.
    // We fuzz one parameter: manager address. We let the fuzzer choose an address and we grant it the MANAGER role
    // in the config before calling pause(). The reference contract sets _paused = true inside _pause(), so
    // paused() must return true. The mutant that always returns false will break this for such manager addresses.
    function testFuzz_property(address manager) public {
        // keep domain wide but exclude zero address to avoid silly cases
        vm.assume(manager != address(0));

        // Grant manager role in cfg: MANAGER keccak256 taken from LRTConstants in original contract
        bytes32 MANAGER = keccak256("MANAGER");
        cfg.setRole(MANAGER, manager, true);

        // call pause() as manager
        vm.prank(manager);
        c.pause();

        // exactly one assertion observing c's public behavior: paused() must be true after pause()
        bool p = c.paused();
        assertTrue(p);
    }
}

