pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: addr is the caller we will grant the manager role to (fuzzer chooses)
    function testFuzz_property(address addr) public {
        // Admissible domain: non-zero address
        vm.assume(addr != address(0));

        // We need an account that is the LRT admin to call updateLRTConfig in initialize and to grant roles.
        // But C.initialize requires a non-zero lrtConfig address; rather than using role mechanics inside lrtConfig,
        // we'll simulate by calling c.initialize with a dummy address and then rely on pause()'s onlyLRTManager modifier
        // which checks IAccessControl(address(lrtConfig)).hasRole(LRTConstants.MANAGER, msg.sender).
        // To make addr succeed as LRT_MANAGER, we deploy a fake LRTConfig that grants MANAGER to everyone.

        // Deploy a permissive fake LRTConfig
        PermissiveLRTConfig lrt = new PermissiveLRTConfig();
        // initialize c with the lrt address
        c.initialize(address(lrt));

        // Ensure addr has some ETH to call (not strictly necessary for pause) but harmless
        vm.deal(addr, 1 ether);

        // Call pause() from addr: since PermissiveLRTConfig.grants the MANAGER role to anyone, this should succeed
        vm.prank(addr);
        c.pause();

        // After pause, reference implementation returns true from paused(); mutant returns false always.
        // We observe paused() and assert it is true. This holds for the correct contract for every admissible addr,
        // but fails on the mutant for some addr (indeed for any addr) because paused() is hardcoded false.
        bool isPaused = c.paused();
        assertTrue(isPaused);
    }
}

// Minimal permissive LRTConfig that satisfies the interface functions used by C
contract PermissiveLRTConfig {
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function getContract(bytes32) external view returns (address) { return address(0); }
    function rsETH() external view returns (address) { return address(0); }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function getContract() external pure returns (address) { return address(0); }

    // IAccessControl.hasRole proxy: grant MANAGER (any role check) to everyone
    function hasRole(bytes32, address) external pure returns (bool) { return true; }

    // minimal stubs used by C
    function getContract(bytes32 id) external view returns (address contractAddr) {
        return address(this);
    }

    function getRSETHPrice() external pure returns (uint256) { return 1; }
    function getAssetPrice(address) external pure returns (uint256) { return 1; }
    function getSupportedAssetList() external pure returns (address[] memory) { return new address[](0); }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }

    // The above duplicate function names are tolerated by the compiler as overloads with different mutability; keep minimal.
}

