pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal mock of IAccessControl behavior for roles used by LRTConfigRoleChecker.
contract MockLRTConfig {
    mapping(bytes32 => mapping(address => bool)) public roles;
    address public oracle;
    address public rseth;
    function setRole(bytes32 role, address who, bool yes) external {
        roles[role][who] = yes;
    }
    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
    // required by C: getContract and rsETH
    function getContract(bytes32) external view returns (address) { return oracle; }
    function rsETH() external view returns (address) { return rseth; }
    // keep other functions/returns minimal stubs
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
}

contract InvMutTest is Test {
    C c;
    MockLRTConfig mock;

    function setUp() public {
        c = new C();
        mock = new MockLRTConfig();
        // initialize c with mock as lrtConfig
        c.initialize(address(mock));
    }

    // fuzzed parameter: an arbitrary address that will act as a manager candidate
    function testFuzz_property(address managerCandidate) public {
        // avoid zero address because role checks typically expect real accounts
        vm.assume(managerCandidate != address(0));

        bytes32 MANAGER = keccak256("MANAGER");

        // By default the candidate is not a manager; set them as manager via mock
        mock.setRole(MANAGER, managerCandidate, true);

        // act as that manager and call pause()
        vm.prank(managerCandidate);
        c.pause();

        // observe paused() via try/catch to follow the required pattern (view doesn't revert here)
        bool ok;
        try c.paused() returns (bool val) {
            // In the reference contract, since we called pause() as a manager, paused() should be true.
            ok = val;
        } catch {
            ok = false;
        }

        // single assertion: reference satisfies that ok is true for all valid managerCandidate inputs
        // (mutant that always returns false will fail for some managerCandidate)
        assertTrue(ok);
    }
}

