pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: addr is any address the fuzzer will try, including zero
    function testFuzz_property(address addr) public {
        // We will call updateLRTConfig with the fuzzed address and observe whether the call succeeds.
        // General rule: reference implementation rejects zero address (call should revert / fail),
        // mutant (with check removed) will allow setting to zero address. We therefore treat the
        // zero address as the distinguishing input which the fuzzer can supply.

        bool ok;
        try c.updateLRTConfig(addr) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: for ANY addr != address(0) the call should succeed on the reference as well as mutant,
        // but for addr == address(0) the reference reverts (so ok==false) while the mutant would set and return ok==true.
        // We assert the universal property that the call succeeds iff the provided addr is NOT the zero address.
        // This holds for the reference (it always reverts on zero and allows non-zero) and is violated by the mutant
        // because the mutant allows zero. The fuzzer supplies addr so it can discover the failing case.

        assertTrue(ok == (addr != address(0)));
    }
}

