    function setUp() public { c = new C(); }

    // Fuzz the candidate address; the property: reference must revert when passed zero address
    function testFuzz_property(address candidate) public {
        // Keep domain wide but ensure we include zero and non-zero addresses
        // No tight assumptions so fuzzer can try address(0)

        bool ok;
        // call updateLRTConfig and record whether it succeeded (ok=true) or reverted (ok=false)
        try c.updateLRTConfig(candidate) {
            ok = true;
        } catch {
            ok = false;
