        // General rule: reference C disallows setting zero address, so call should revert when candidate==address(0)
        // This assertion holds for the correct contract for ALL inputs: if candidate==address(0) then ok must be false.
        assertTrue(!(candidate == address(0)) || ok == false);
    }
}

