contract InvMutTest is Test {
    C c;
    MockLRTConfigAdmin adminStub;

    function setUp() public {
        c = new C();
    }

    // fuzzer supplies an address param 'caller' which will act as the admin account calling updateLRTConfig,
    // and an address 'newConfig' which is the candidate lrtConfig address to set. We keep domains wide.
    function testFuzz_property(address caller, address newConfig) public {
        // keep caller non-zero so it can be set as admin in our stub
        vm.assume(caller != address(0));

        // deploy a minimal admin stub that reports `caller` as having DEFAULT_ADMIN_ROLE
        adminStub = new MockLRTConfigAdmin(caller);

        // initialize contract with a valid non-zero lrtConfig to allow initializer logic
        // use adminStub address as initial config (non-zero)
        // Need to call initialize via admin role bypass: initialize is external and doesn't require roles
        c.initialize(address(adminStub));

        // Make 'caller' be the tx.origin/msg.sender for the subsequent updateLRTConfig call
        vm.prank(caller);

        // Attempt updateLRTConfig with fuzzed newConfig. We capture whether the call succeeded.
        bool ok;
        try c.updateLRTConfig(newConfig) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: After the attempted update (whether it reverted or not), the stored lrtConfig
        // (public lrtConfig getter via the autogenerated storage getter) must NOT be the zero address
        // for the REFERENCE implementation for ALL inputs — the reference enforces non-zero via UtilLib.
        // The mutant that removed the check will allow setting zero and thus violate this for some input.
        assertTrue(c.lrtConfig() != address(0));
    }
}

