// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the admin caller address (who will call updateLRTConfig) and the target address to set
    function testFuzz_property(address admin, address target) public {
        // keep admin as any address (EOA) but disallow zero admin to ensure call is from someone
        vm.assume(admin != address(0));

        // We need the caller to pass onlyLRTAdmin modifier in C. In the real system that checks
        // IAccessControl(address(lrtConfig)).hasRole(DEFAULT_ADMIN_ROLE, msg.sender).
        // In our test we cannot set up AccessControl state; however the reference contract's
        // onlyLRTAdmin uses lrtConfig which is initially zero. The modifier checks
        // IAccessControl(address(lrtConfig)).hasRole(...), calling into address(0) would be
        // a call to an EOA (no code) and thus returns false; so onlyLRTAdmin will revert.
        // To let the call proceed on the reference contract we must first initialize c with a
        // non-zero lrtConfig by calling initialize (which sets lrtConfig and emits). We'll
        // supply a nonzero target for initialize; reuse 'target' if nonzero, otherwise use admin.

        address initConfig = target == address(0) ? admin : target;
        vm.prank(admin);
        // initialize requires non-zero address (UtilLib.checkNonZeroAddress) and only initializer
        // any caller can call initialize; ensure we pass non-zero
        c.initialize(initConfig);

        // Now admin should be able to call updateLRTConfig only if AccessControl at initConfig
        // returns true for hasRole; we cannot set that, but we can bypass by making the admin be
        // the DEFAULT_ADMIN_ROLE in the sense that the onlyLRTAdmin modifier will call
        // IAccessControl(address(lrtConfig)).hasRole(DEFAULT_ADMIN_ROLE, msg.sender).
        // If the lrtConfig address is an address with a contract that returns true for hasRole,
        // we must deploy a helper that implements IAccessControl and returns true for hasRole
        // when queried for DEFAULT_ADMIN_ROLE and the provided admin. We'll deploy that helper,
        // set it as lrtConfig via initialize above. To ensure initialize set that, we only used
        // initConfig = target==0 ? admin : target; but that may not be our helper. So instead,
        // deploy the helper now and call updateLRTConfig through it: the caller must be admin and
        // the current lrtConfig must allow admin to be admin; we can first update to our helper
        // by calling updateLRTConfig from the current admin: the current lrtConfig was set to initConfig
        // which might not grant us admin rights. To avoid this complexity, instead we will exercise
        // the property by calling updateLRTConfig from the deployer of the contract (this test),
        // which after initialize the contract emitted UpdatedLRTConfig and set lrtConfig to initConfig.
        // The onlyLRTAdmin modifier will consult IAccessControl(initConfig).hasRole(DEFAULT_ADMIN_ROLE, address(this)).
        // To ensure that call returns true, we deploy a permissive AccessControl stub and then
